import{az as e,P as t,Q as o,aQ as s}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const D=JSON.parse('{"title":"hydrate（水合）","description":"","frontmatter":{},"headers":[],"relativePath":"框架/react/react/hydrate.md","filePath":"框架/react/react/hydrate.md","lastUpdated":1785246304000}'),r={name:"框架/react/react/hydrate.md"};function l(n,a,d,c,p,i){return t(),o("div",null,[...a[0]||(a[0]=[s(`<h1 id="hydrate-水合" tabindex="-1">hydrate（水合） <a class="header-anchor" href="#hydrate-水合" aria-label="Permalink to “hydrate（水合）”">​</a></h1><p><code>hydrate</code> 用于 <strong>SSR</strong>：服务端已经输出了 HTML，客户端 React 不再从头 <code>create</code> DOM，而是<strong>接管已有 DOM</strong>，补上事件与状态。</p><h2 id="作用流程" tabindex="-1">作用流程 <a class="header-anchor" href="#作用流程" aria-label="Permalink to “作用流程”">​</a></h2><ol><li>服务端渲染出完整 HTML 并返回</li><li>浏览器先展示这份 HTML（首屏更快）</li><li>客户端 JS 执行水合，把组件树与现有 DOM 对齐</li><li>之后交互由 React 接管</li></ol><h2 id="现代-api" tabindex="-1">现代 API <a class="header-anchor" href="#现代-api" aria-label="Permalink to “现代 API”">​</a></h2><p>React 18 起推荐 <code>hydrateRoot</code>（旧的 <code>ReactDOM.hydrate</code> 仍能见到，属遗留）：</p><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#89DDFF;"> {</span><span style="color:#BABED8;"> hydrateRoot</span><span style="color:#89DDFF;"> }</span><span style="color:#89DDFF;font-style:italic;"> from</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">react-dom/client</span><span style="color:#89DDFF;">&#39;</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#BABED8;"> App </span><span style="color:#89DDFF;font-style:italic;">from</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">./App</span><span style="color:#89DDFF;">&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#82AAFF;">hydrateRoot</span><span style="color:#BABED8;">(document</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">getElementById</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">root</span><span style="color:#89DDFF;">&#39;</span><span style="color:#BABED8;">)</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> &lt;</span><span style="color:#FFCB6B;">App</span><span style="color:#89DDFF;"> /&gt;</span><span style="color:#BABED8;">)</span></span></code></pre></div><p>纯客户端、没有服务端 HTML 时，用 <code>createRoot(...).render(...)</code>，不需要 hydrate。</p><h2 id="与-render-的区别" tabindex="-1">与 render 的区别 <a class="header-anchor" href="#与-render-的区别" aria-label="Permalink to “与 render 的区别”">​</a></h2><table tabindex="0"><thead><tr><th></th><th>客户端 <code>render</code></th><th><code>hydrate</code></th></tr></thead><tbody><tr><td>DOM</td><td>由 React 创建</td><td>复用服务端已有 HTML</td></tr><tr><td>场景</td><td>CSR / SPA</td><td>SSR / 部分静态出 HTML</td></tr><tr><td>一致性</td><td>无「对齐」要求</td><td>要求首屏 HTML 与客户端首渲一致</td></tr></tbody></table><p>若服务端 HTML 与客户端第一次渲染结果不一致，可能出现警告、闪烁或错误复用节点。</p><h2 id="注意点" tabindex="-1">注意点 <a class="header-anchor" href="#注意点" aria-label="Permalink to “注意点”">​</a></h2><ul><li>水合阶段应避免在首渲就产出与服务端不同的内容（如直接读 <code>window</code>、随机数、<code>Date.now()</code>）</li><li>仅客户端才有的逻辑可放到 <code>useEffect</code> 里，等水合后再跑</li><li>框架（Next.js 等）通常已封装水合，业务里较少手写 <code>hydrateRoot</code></li></ul><h2 id="和渲染机制的关系" tabindex="-1">和渲染机制的关系 <a class="header-anchor" href="#和渲染机制的关系" aria-label="Permalink to “和渲染机制的关系”">​</a></h2><p>水合同样会走协调：用客户端虚拟树去匹配现有 DOM。编译型框架（如 Vue）还能借静态标记加速水合；React 侧则更多依赖一致的首渲输出与后续并发能力。</p><p>相关：<a href="./渲染机制">渲染机制</a>、<a href="./双阶段">双阶段</a>。</p><h2 id="简单理解" tabindex="-1">简单理解 <a class="header-anchor" href="#简单理解" aria-label="Permalink to “简单理解”">​</a></h2><p><code>render</code> 是「从零搭界面」；<code>hydrate</code> 是「把服务端搭好的界面接上线和电」。</p>`,18)])])}const F=e(r,[["render",l]]);export{D as __pageData,F as default};
